# Homebrew cask for Threadly. Generated by scripts/release.sh from this template;
# the result goes to the tap repository as Casks/threadly.rb.
cask "threadly" do
  version "0.2.1"
  sha256 "103f8d145a5e5f787d918dd4c0d89b3f1865c257391e323747e6b527bf266df6"

  url "https://github.com/Mansfera/threadly/releases/download/v#{version}/Threadly_#{version}_aarch64.dmg"
  name "Threadly"
  desc "Email as chat: several mail accounts shown as a messenger"
  homepage "https://github.com/Mansfera/threadly"

  depends_on arch: :arm64
  depends_on :macos

  app "Threadly.app"

  # Threadly is not notarized (that needs a paid Apple Developer ID), so macOS would refuse
  # to open a quarantined download. Clearing the quarantine flag is what "Open Anyway" does.
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/Threadly.app"]
  end

  # Account passwords and sign-in tokens live in the Keychain (service com.mansfera.threadly);
  # remove accounts in Settings before uninstalling to delete them.
  zap trash: [
    "~/Library/Application Support/com.mansfera.threadly",
    "~/Library/Caches/com.mansfera.threadly",
    "~/Library/WebKit/com.mansfera.threadly",
  ]
end
